{"hypotheses": [
  {
    "name": "Organizational Capital and Analyst Disagreement Synergy",
    "mechanism": "Firms with high organizational capital (OrgCap) and high analyst forecast dispersion (ForecastDispersion) are likely to be underappreciated due to complexity and information asymmetry. Combining these captures mispricing from both intangible investment and disagreement, which should be more persistent than either alone.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "OrgCap"},
        {"weight": 1.0, "primitive": "ForecastDispersion"},
        {"weight": -0.5, "primitive": "AnalystRevision"}
      ],
      "regime": "VIX_ABOVE_TRAILING_MEDIAN",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "VIX_ABOVE_TRAILING_MEDIAN", "direction": "higher"},
      {"type": "size_segment", "segment": "small", "direction": "stronger"},
      {"type": "correlation", "primitive": "OrgCap", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.85,
    "expected_decay_half_life_months": 36
  },
  {
    "name": "Customer Momentum and Deferred Revenue Growth",
    "mechanism": "Firms with strong customer momentum (iomom_cust) and rising deferred revenue (DelDRC) signal robust demand and future revenue recognition. The combination exploits forward-looking demand signals and revenue recognition timing, which are not fully captured by price momentum or accruals alone.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "iomom_cust"},
        {"weight": 0.5, "primitive": "DelDRC"},
        {"weight": -0.5, "primitive": "Accruals"}
      ],
      "regime": null,
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "size_segment", "segment": "micro", "direction": "stronger"},
      {"type": "international", "region": "emerging", "direction": "same_sign"},
      {"type": "correlation", "primitive": "iomom_cust", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.75,
    "expected_decay_half_life_months": 24
  },
  {
    "name": "Patent Intensity and Real Estate Holdings",
    "mechanism": "Firms with high patent intensity (PatentsRD) but low real estate holdings (realestate) are likely to be asset-light innovators. This composite captures the premium for scalable innovation while avoiding capital-intensive, less scalable business models.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "PatentsRD"},
        {"weight": -1.0, "primitive": "realestate"}
      ],
      "regime": "TERM_SPREAD_POSITIVE",
      "vol_target": false
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "TERM_SPREAD_POSITIVE", "direction": "higher"},
      {"type": "size_segment", "segment": "large", "direction": "stronger"},
      {"type": "international", "region": "developed_ex_us", "direction": "same_sign"}
    ],
    "expected_annualized_sharpe": 0.65,
    "expected_decay_half_life_months": 48
  },
  {
    "name": "Option Volume and Analyst Optimism Divergence",
    "mechanism": "Stocks with high option trading volume (OptionVolume1) and low analyst optimism (AOP) may be subject to informed trading not yet reflected in consensus forecasts. The composite exploits the lag between derivative market signals and analyst sentiment.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "OptionVolume1"},
        {"weight": -1.0, "primitive": "AOP"}
      ],
      "regime": "MKT_TRAILING_12M_DOWN",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "MKT_TRAILING_12M_DOWN", "direction": "higher"},
      {"type": "size_segment", "segment": "mega", "direction": "stronger"},
      {"type": "correlation", "primitive": "OptionVolume1", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.7,
    "expected_decay_half_life_months": 18
  },
  {
    "name": "Industry Concentration and Deferred Tax Change",
    "mechanism": "Firms in highly concentrated industries (Herf) with positive changes in deferred taxes (ChTax) may benefit from market power and tax management, leading to persistent abnormal profits not captured by standard profitability or value factors.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "Herf"},
        {"weight": 0.5, "primitive": "ChTax"}
      ],
      "regime": null,
      "vol_target": false
    },
    "auxiliary_predictions": [
      {"type": "size_segment", "segment": "large", "direction": "stronger"},
      {"type": "international", "region": "developed_ex_us", "direction": "same_sign"},
      {"type": "subperiod_consistency"}
    ],
    "expected_annualized_sharpe": 0.6,
    "expected_decay_half_life_months": 60
  },
  {
    "name": "Share Repurchase and Idiosyncratic Volatility Spread",
    "mechanism": "Firms with high share repurchases (ShareRepurchase) and low idiosyncratic volatility (IdioVol3F) are likely to be returning capital from stable cash flows, signaling undervaluation and discipline. The combination avoids riskier buybacks and focuses on sustainable capital return.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "ShareRepurchase"},
        {"weight": -1.0, "primitive": "IdioVol3F"}
      ],
      "regime": "TERM_SPREAD_NEGATIVE",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "TERM_SPREAD_NEGATIVE", "direction": "higher"},
      {"type": "size_segment", "segment": "large", "direction": "stronger"},
      {"type": "correlation", "primitive": "ShareRepurchase", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.8,
    "expected_decay_half_life_months": 30
  },
  {
    "name": "Pension Funding and Deferred Revenue",
    "mechanism": "Firms with strong pension funding status (FR) and rising deferred revenue (DelDRC) are likely to have both financial stability and robust future revenue, reducing risk of distress and supporting higher valuations. The composite captures a unique intersection of balance sheet strength and forward sales.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "FR"},
        {"weight": 1.0, "primitive": "DelDRC"}
      ],
      "regime": null,
      "vol_target": false
    },
    "auxiliary_predictions": [
      {"type": "size_segment", "segment": "large", "direction": "stronger"},
      {"type": "international", "region": "developed_ex_us", "direction": "same_sign"},
      {"type": "subperiod_consistency"}
    ],
    "expected_annualized_sharpe": 0.55,
    "expected_decay_half_life_months": 72
  },
  {
    "name": "Analyst Value and Convertible Debt Aversion",
    "mechanism": "Stocks with high analyst value (AnalystValue) but no convertible debt (ConvDebt) are likely to be fundamentally undervalued without the dilution risk associated with convertibles. This composite isolates analyst-identified value that is less likely to be arbitraged away by capital structure complexity.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "AnalystValue"},
        {"weight": -1.0, "primitive": "ConvDebt"}
      ],
      "regime": "VIX_BELOW_TRAILING_MEDIAN",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "VIX_BELOW_TRAILING_MEDIAN", "direction": "higher"},
      {"type": "size_segment", "segment": "small", "direction": "stronger"},
      {"type": "correlation", "primitive": "AnalystValue", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.7,
    "expected_decay_half_life_months": 20
  }
]}
